    private IEnumerable<WorkOrderListDto> _workOrders = [];
    private bool _isLoading = true;
    private string _searchTerm = string.Empty;
    private WorkOrderStatus? _statusFilter;
    private ConfirmationModal? _confirmModal;
    private int _deleteWoId;
    private string _deleteMessage = string.Empty;
    private Dictionary<int, bool> _producibleMap = [];

    private IEnumerable<WorkOrderListDto> FilteredWorkOrders
    {
        get
        {
            var query = _workOrders;

            if (!string.IsNullOrWhiteSpace(_searchTerm))
            {
                query = query.Where(w =>
                    w.WorkOrderNo.Contains(_searchTerm, StringComparison.OrdinalIgnoreCase) ||
                    w.ItemCode.Contains(_searchTerm, StringComparison.OrdinalIgnoreCase) ||
                    w.ItemName.Contains(_searchTerm, StringComparison.OrdinalIgnoreCase));
            }

            if (_statusFilter.HasValue)
            {
                query = query.Where(w => w.Status == _statusFilter.Value);
            }

            return query;
        }
    }

    [Parameter]
    [SupplyParameterFromQuery(Name = "search")]
    public string? SearchQuery { get; set; }

    protected override async Task OnInitializedAsync()
    {
        if (!string.IsNullOrEmpty(SearchQuery))
        {
            _searchTerm = SearchQuery;
        }
        await LoadWorkOrdersAsync();
    }

    private async Task LoadWorkOrdersAsync()
    {
        _isLoading = true;
        try
        {
            var result = await WorkOrderService.GetAllAsync();
            if (result.Success)
            {
                _workOrders = result.Data;
                _producibleMap.Clear();

                var releasedWOs = _workOrders.Where(w => w.Status == WorkOrderStatus.Released).ToList();
                if (releasedWOs.Any())
                {
                    var itemsResult = await ItemService.GetAllAsync();
                    var bomsResult = await BOMService.GetAllAsync();

                    if (itemsResult.Success && bomsResult.Success)
                    {
                        var stockDict = itemsResult.Data.ToDictionary(i => i.ItemCode, i => i.StockQuantity);
                        var activeBOMs = bomsResult.Data.Where(b => b.IsActive).ToList();

                        foreach (var wo in releasedWOs)
                        {
                            var activeBOM = activeBOMs.FirstOrDefault(b => b.ParentItemCode == wo.ItemCode);
                            if (activeBOM == null)
                            {
                                _producibleMap[wo.Id] = false;
                                continue;
                            }

                            var bomDetailResult = await BOMService.GetByIdAsync(activeBOM.Id);
                            if (bomDetailResult.Success && bomDetailResult.Data.Lines != null)
                            {
                                bool canBeCompleted = true;
                                foreach (var line in bomDetailResult.Data.Lines)
                                {
                                    decimal neededQty = (line.Quantity * wo.TargetQuantity) / bomDetailResult.Data.BaseQuantity;
                                    if (line.ScrapRate > 0)
                                    {
                                        neededQty = neededQty * (1 + line.ScrapRate / 100);
                                    }

                                    stockDict.TryGetValue(line.ChildItemCode, out var currentStock);
                                    if (currentStock < neededQty)
                                    {
                                        canBeCompleted = false;
                                        break;
                                    }
                                }
                                _producibleMap[wo.Id] = canBeCompleted;
                            }
                            else
                            {
                                _producibleMap[wo.Id] = false;
                            }
                        }
                    }
                }
            }
            else
            {
                ToastService.ShowError(result.Message);
            }
        }
        catch (Exception ex)
        {
            ToastService.ShowError($"İş emirleri yüklenirken hata oluştu: {ex.Message}");
        }
        finally
        {
            _isLoading = false;
        }
    }

    private async Task UpdateStatus(int id, WorkOrderStatus status)
    {
        try
        {
            var result = await WorkOrderService.UpdateStatusAsync(id, status);
            if (result.Success)
            {
                ToastService.ShowSuccess(result.Message);
                await LoadWorkOrdersAsync();
            }
            else
            {
                ToastService.ShowError(result.Message);
            }
        }
        catch (Exception ex)
        {
            ToastService.ShowError($"Statü güncellenirken hata oluştu: {ex.Message}");
        }
    }

    private void ConfirmDelete(WorkOrderListDto wo)
    {
        _deleteWoId = wo.Id;
        _deleteMessage = $"'{wo.WorkOrderNo}' numaralı taslak iş emrini silmek istediğinizden emin misiniz? Bu işlem geri alınamaz.";
        _confirmModal?.Show();
    }

    private async Task ExecuteDelete()
    {
        try
        {
            var result = await WorkOrderService.DeleteAsync(_deleteWoId);
            if (result.Success)
            {
                ToastService.ShowSuccess("İş emri başarıyla silindi.");
                await LoadWorkOrdersAsync();
            }
            else
            {
                ToastService.ShowError(result.Message);
            }
        }
        catch (Exception ex)
        {
            ToastService.ShowError($"Silme işlemi sırasında hata oluştu: {ex.Message}");
        }
    }

    private void ClearFilters()
    {
        _searchTerm = string.Empty;
        _statusFilter = null;
    }

    private static string GetStatusDisplayName(WorkOrderStatus status) => status switch
    {
        WorkOrderStatus.Draft => "Taslak",
        WorkOrderStatus.Released => "Üretimde",
        WorkOrderStatus.Completed => "Tamamlandı",
        WorkOrderStatus.Cancelled => "İptal Edildi",
        _ => status.ToString()
    };

    private static string GetStatusBadgeClass(WorkOrderStatus status) => status switch
    {
        WorkOrderStatus.Draft => "bg-secondary text-white",
        WorkOrderStatus.Released => "bg-warning text-dark",
        WorkOrderStatus.Completed => "bg-success text-white",
        WorkOrderStatus.Cancelled => "bg-danger text-white",
        _ => "bg-light text-dark"
    };

